prologue:
/* One row of scores.dat. Everything below reads through this, because the game hands the
   whole row over at once and the fields are only interesting one at a time */
static MOD_UNUSED int scores_read(int index, AmodScoreEntry* out) {
    if (API->scores == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->scores->Get(SELF, index, out);
}

static MOD_UNUSED const char* scores_name(int index) {
    const char* name = API->scores != 0 ? API->scores->GetName(SELF, index) : 0;
    return name != 0 ? name : "";
}

static MOD_UNUSED const char* scores_level(int index) {
    AmodScoreEntry row;
    if (scores_read(index, &row) == 0 || row.level == 0) return "";
    return row.level;
}

static MOD_UNUSED float scores_time(int index) {
    AmodScoreEntry row;
    return scores_read(index, &row) != 0 ? row.time : 0.0f;
}

static MOD_UNUSED int scores_point(int index) {
    return API->scores != 0 ? API->scores->GetPoint(SELF, index) : 0;
}

/* 0 is the castle, 1 the place inside it, 2 whether the row survives the next save */
static MOD_UNUSED int scores_field(int index, int which) {
    AmodScoreEntry row;
    if (scores_read(index, &row) == 0) return -1;
    if (which == 0) return row.castle;
    if (which == 1) return row.inCastle;
    return row.filled;
}

/* The place of the first row with this name, or -1: a sheet names a player, not a number */
static MOD_UNUSED int scores_find(const char* name) {
    const int count = API->scores != 0 ? API->scores->Count(SELF) : 0;
    int at;
    for (at = 0; at < count; ++at)
        if (strcmp(scores_name(at), name) == 0) return at;
    return -1;
}

/* The highest score of a castle, or -1 when the castle holds nothing */
static MOD_UNUSED int scores_best(int castle) {
    const int count = API->scores != 0 ? API->scores->Count(SELF) : 0;
    int at, best = -1, most = 0;
    for (at = 0; at < count; ++at) {
        AmodScoreEntry row;
        if (scores_read(at, &row) == 0 || row.castle != castle) continue;
        if (best >= 0 && row.score <= most) continue;
        best = at;
        most = row.score;
    }
    return best;
}

static MOD_UNUSED int scores_castle_of(const char* level) {
    return API->scores != 0 ? API->scores->CastleOfLevel(SELF, level) : -1;
}

static MOD_UNUSED int scores_in_castle(int castle) {
    return API->scores != 0 ? API->scores->CastleEntryCount(SELF, castle) : 0;
}
